entries[201788] = { ["name"] = "Vicious Sabertooth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon a Vicious Sabertooth.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The elite Horde forces that use these sabertooth mounts use a battle cry that translates from Thalassian as \"pspspspsps\".\"\nPvP:\nDragonflight: Season 1\nRated Arena and Rated Battleground Season Reward" }
entries[201789] = { ["name"] = "Vicious Sabertooth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon a Vicious Sabertooth.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The elite Alliance forces that use these sabertooth mounts use a battle cry that translates from Darnassian as \"here kitty kitty\".\"\nPvP:\nDragonflight: Season 1\nRated Arena and Rated Battleground Season Reward" }
