entries[202612] = { ["name"] = "Screaming Black Dragonscale", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+473 [Agility or Strength or Intellect]\nEquip: Your attacks and abilities have a chance to grant you ephemeral dragon wings, increasing your Critical Strike by 1022 and your Leech by 285 for 15 sec. (15s cooldown)\nUse: Call upon an echo of Neltharion's power to crash to the ground below you, dealing 24246 Shadowflame damage to nearby enemies if you have traveled at least 15 yards. (3 Min Cooldown)\nSell Price:" }
entries[202613] = { ["name"] = "Zaqali Chaos Grapnel", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+447 Strength\nUse: Hurl the grapnel up to 20 yds to impale your target, dealing 61039 Physical damage and heaving you towards them with tremendous force. On impact, deal 83082 Volcanic damage split between all nearby enemies.\n\nImpact damage is increased per enemy struck, up to 5 enemies. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[202614] = { ["name"] = "Rashok's Molten Heart", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+460 Intellect\nEquip: Your healing spells have a chance to awaken the Heart, restoring ( 146 * 10) mana over 10 sec and causing your healing spells to restore ( 1491 * 10) additional health over 10 sec.\n\nOverhealing from this effect invigorates your target, granting them up to 380 Versatility for 12 sec. (10s cooldown)\nSell Price:" }
entries[202615] = { ["name"] = "Vessel of Searing Shadow", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+447 Intellect\nEquip: Your harmful spells have a high chance to draw unstable flames from the Vessel, increasing your Haste by 90 and dealing ( 133 * 30 / 3) Fire damage to you over 30 sec.\n\nUpon reaching 5 stacks the flames leap toward your target, combusting immediately for 29019 Shadow damage, then burning them for ( 7255 * 6) Shadowflame damage over 12 seconds.\nSell Price:" }
entries[202616] = { ["name"] = "Enduring Dreadplate", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+447 [Agility or Strength]\nUse: Cover yourself with 5 Hellsteel Plates, reducing damage taken by 5320 and your movement speed by 3% per plate, for 15 sec.\n\nTaking 44323 damage ruptures one plate, removing it and releasing forth a pillar of Shadowflame that deals 19593 damage to all enemies in its path. This effect may only occur once every 2 sec. Upon expiration, all remaining plates rupture. (2s cooldown) (2 Min Cooldown)\nSell Price:" }
entries[202617] = { ["name"] = "Elementium Pocket Anvil", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+447 [Agility or Strength]\nEquip: Sharpen your weapon with Elementium, giving your [melee damage dealer specialization's main class ability] a chance to deal ( 37814 * 0.6) additional Shadowflame damage on-hit.\nUse: Strike your weapon against the anvil to strengthen it further, dealing 7221 Shadowflame damage to nearby enemies and increasing the on-hit damage by 33% until shortly after leaving combat. Stacks 5 times. (1 Min Cooldown)\nSell Price:" }
