entries[202667] = { ["name"] = "Sealed Artifact Scroll", ["text"] = "Dragon Isles Artifacts\nBinds when picked up\nUse: Marks the location of a special treasure on your map.\n\"A magically sealed scroll regarding the location of a forgotten artifact in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Dragonscale Expedition.\"" }
entries[202668] = { ["name"] = "Sealed Spirit Scroll", ["text"] = "Dragon Isles Artifacts\nBinds when picked up\nUse: Marks the location of a special treasure on your map.\n\"A magically sealed scroll regarding the location of a spirit beast in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Maruuk Centaur.\"" }
entries[202669] = { ["name"] = "Sealed Fish Scroll", ["text"] = "Dragon Isles Artifacts\nBinds when picked up\nUse: Marks the location of a special treasure on your map.\n\"A magically sealed scroll regarding the location of a rare fish within the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Iskaara Tuskarr.\"" }
entries[202670] = { ["name"] = "Sealed Knowledge Scroll", ["text"] = "Dragon Isles Artifacts\nBinds when picked up\nUse: Marks the location of a special treasure on your map.\n\"A magically sealed scroll regarding the location of hidden knowledge in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Valdrakken Accord.\"" }
entries[202690] = { ["name"] = "Decorative Shrubbery", ["text"] = "Quest Item\nUnique\n\"A nicely-shaped shrub with a certain pizzazz.\"" }
entries[202691] = { ["name"] = "Henry's Handbag", ["text"] = "Binds when picked up\nUnique\n10 Slot Reagent Bag\nSell Price:" }
entries[202692] = { ["name"] = "Gnoll Fiend Flail", ["text"] = "Binds when picked up\nOne-Hand Mace\n37 - 49 Damage Speed 2.60\n(16.5 damage per second)\n+15 [Agility or Strength]\n+22 Stamina\n+ 29 Critical Strike\nDurability 110 / 110\n\"Gnoll jaws break bones easy, they use these just for the fun of it.\"\nSell Price:" }
entries[202693] = { ["name"] = "Dragonfruit Pie", ["text"] = "Quest Item\n\"Flame-baked with love.\"" }
entries[202694] = { ["name"] = "Loamy Soil", ["text"] = "Quest Item\n\"Enriched with nutrients from the Dream.\"" }
entries[202695] = { ["name"] = "Ancient Water", ["text"] = "Quest Item\n\"The water seems to stay the perfect, refreshing temperature.\"" }
entries[202696] = { ["name"] = "Comforting Ducky", ["text"] = "Quest Item\n\"A soft plush that has been loved by many hatchlings.\"" }
entries[202697] = { ["name"] = "Crimson Cushion", ["text"] = "Quest Item\n\"The pinnacle of whelp comfort.\"" }
entries[202698] = { ["name"] = "The Dragonkin Voice 4: Might & Right", ["text"] = "Quest Item\n\"The dragons have ruled us because theY're stronger than we. But together, in our great numbers, we're stronger than they. If might makes right, then we are right, if we haVe courage to riSe up together. - Instigator Belaphon\"" }
entries[202699] = { ["name"] = "The Dragonkin Voice 2: 100 Centuries Abandoned", ["text"] = "Quest Item\n\"FoR 100 Years, theY left us alone, while we tended to \"their\" isles, guarded \"their\" cities and roads, and kept the peace. TheY haVe repeated that abandonment 99 more times. Should we welcome them with open arms, and obey as before? - Instigator Belaphon\"" }
entries[202700] = { ["name"] = "The Dragonkin Voice 3: 100 Centuries Independent", ["text"] = "Quest Item\n\"The dragons returned expecting us to Be what we were, but in tHose 100 Centuries, we changed. We grew. We serve them no longer, and are serFs no longer. We've chosen our Path for 10,000 years, and we will do so again. - Instigator Belaphon\"" }
entries[202701] = { ["name"] = "The Dragonkin Voice 5: The Rebel Code", ["text"] = "Quest Item\n\"And so we Swear one and all to the rebel code. No ruler but one's selF. No purpose but independence. No flight but the flightless. - Instigator Belaphon\"" }
entries[202702] = { ["name"] = "The Dragonkin Voice 1: A Dragonkin's Worth", ["text"] = "Quest Item\n\"The dragons believE they're worth more than us. That's why Sendrax had to sacrifice herself, foR a dragon egg that might not even be viable. They say she's a herO, but she's really their victim. - Instigator Belaphon\"" }
entries[202703] = { ["name"] = "Ephemeral Sand", ["text"] = "Quest Item\n\"The grains of sand disappear as you watch it.\"" }
entries[202705] = { ["name"] = "Snail Slime", ["text"] = "Quest Item\n\"Slime collected from snails that is perfect for making incense\"" }
entries[202706] = { ["name"] = "Zandali Piri Piri", ["text"] = "Quest Item\n\"Small peppers grown in the jungles of Zandalar. They are extremely hot!\"\nSell Price:" }
entries[202707] = { ["name"] = "Un'goro Coconut", ["text"] = "Quest Item\n\"Hard outside, sweet and delicious inside. Loved by gorillas.\"\nSell Price:" }
entries[202708] = { ["name"] = "Curried Coconut Crab", ["text"] = "Quest Item\n\"Crab stewed with exotic spices and coconut milk.\"" }
entries[202709] = { ["name"] = "Spicy Seared Talbuk Steak", ["text"] = "Quest Item\n\"Talbuk steak that has been dry-rubbed and then cooked in searing flames.\"" }
entries[202710] = { ["name"] = "Grilled Southfury Salmon", ["text"] = "Quest Item\n\"Salmon seasoned with spices and then grilled. Served with lemon.\"" }
entries[202711] = { ["name"] = "Lost Compass", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Hold out your compass.\n\"And though one foot sits firm and centered, the circle is complete as the other ends where it began.\"\nSell Price:" }
entries[202712] = { ["name"] = "Rubber Fish", ["text"] = "Use: Play fetch with most Companion Pets. (3 Sec Cooldown)\nSell Price:" }
entries[202713] = { ["name"] = "Scattered Supplies", ["text"] = "Quest Item\n\"Some of Jeb and Tacha's expedition gear.\"" }
entries[202714] = { ["name"] = "M.U.S.T", ["text"] = "Quest Item\nUse: Used to detoxify the corroded mind of a retfi. (2s cooldown)\n\"The \"Multi Usage Storage Tank\", or M.U.S.T, can siphon different types of energy and store them to act like a battery.\"" }
