entries[203226] = { ["name"] = "Stormfused Salamanther", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[203227] = { ["name"] = "Brewing Supplies?", ["text"] = "Quest Item\n\"These rubbery, bitter lichen have been preserved in a sweet brine, adding a tangy kick that cuts through the sour, earthen smell they exude.\"" }
